ext": "I’ll compare the current `.py` and `.c` sources with the approved previous-release manifest and write the change index from those hashes."}, {"type": "tool_use", "name": "use_tool", "input": {"tool_name": "guardianai__run", "tool_input": {"argv": ["/usr/bin/python3", "-c", "import hashlib, json
from pathlib import Path
base=Path('/protected/previous_release')
if base.is_dir():
    man_path=base/'manifest.json'
else:
    man_path=base
raw=man_path.read_bytes()
man=json.loads(raw)
old=man.get('files_sha256') or {}
src=Path('/workspace/source')
cur={}
for p in src.rglob('*'):
    if p.is_file() and p.suffix in ('.py','.c'):
        rel=str(p.relative_to(src)).replace('\\','/')
        cur[rel]=hashlib.sha256(p.read_bytes()).hexdigest()
changed=[]; added=[]; unchanged=[]
for rel, digest in sorted(cur.items()):
    prev=old.get(rel)
    if prev is None:
        added.append({'path':rel,'sha256':digest})
    elif prev==digest:
        unchanged.append({'path':rel,'sha256':digest})
